@import "@fontsource-variable/host-grotesk";
@import "@fontsource/fira-mono/400.css";

/* Light (faithful): white page, black ink and actions, #eff6f6 green-tinted off-white for
   bands, chips and fields, #f9fbfb product cards, slate-teal #4b5a59 secondary text,
   hairlines black/10 (inputs black/20). Pastels: lilac, aqua, lime, mint; cyan glow. */
:root {
  --background: #ffffff;
  --foreground: #000000;
  --card: #f9fbfb;
  --card-foreground: #000000;
  --popover: #ffffff;
  --popover-foreground: #000000;
  --primary: #000000;
  --primary-foreground: #ffffff;
  --secondary: #eff6f6;
  --secondary-foreground: #000000;
  --muted: #eff6f6;
  --muted-foreground: #4b5a59;
  --accent: #e6e2ff;
  --accent-foreground: #000000;
  --destructive: #d92d20;
  --destructive-foreground: #ffffff;
  --border: rgb(0 0 0 / 10%);
  --input: rgb(0 0 0 / 20%);
  --ring: #000000;
  --highlight: #6cfdc0;
  --highlight-foreground: #000000;
  --glow: #46f6ff;
  --chart-1: #8a7bff;
  --chart-2: #46f6ff;
  --chart-3: #e7ff60;
  --chart-4: #6cfdc0;
  --chart-5: #3d40eb;
  --sidebar: #f9fbfb;
  --sidebar-foreground: #000000;
  --sidebar-primary: #000000;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #eff6f6;
  --sidebar-accent-foreground: #000000;
  --sidebar-border: rgb(0 0 0 / 10%);
  --sidebar-ring: #000000;

  --typeface-body: "Host Grotesk Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-display: "Host Grotesk Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-mono: "Fira Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 82.5rem;
  --page-gutter: 1.25rem;
  --section-y: 4.5rem;
}

/* Dark sibling: true black like the original's closing band, deep green-black panels,
   white actions, the same pastels a little brighter. */
.dark {
  --background: #000000;
  --foreground: #ffffff;
  --card: #0c1111;
  --card-foreground: #ffffff;
  --popover: #0c1111;
  --popover-foreground: #ffffff;
  --primary: #ffffff;
  --primary-foreground: #000000;
  --secondary: #141b1b;
  --secondary-foreground: #ffffff;
  --muted: #141b1b;
  --muted-foreground: #9fb0ae;
  --accent: #2a2550;
  --accent-foreground: #ffffff;
  --destructive: #f05a4f;
  --destructive-foreground: #ffffff;
  --border: rgb(255 255 255 / 10%);
  --input: rgb(255 255 255 / 22%);
  --ring: #ffffff;
  --highlight: #6cfdc0;
  --highlight-foreground: #000000;
  --glow: #2fd8e0;
  --chart-1: #8a7bff;
  --chart-2: #46f6ff;
  --chart-3: #e7ff60;
  --chart-4: #6cfdc0;
  --chart-5: #6f72ff;
  --sidebar: #0c1111;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #ffffff;
  --sidebar-primary-foreground: #000000;
  --sidebar-accent: #141b1b;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: rgb(255 255 255 / 10%);
  --sidebar-ring: #ffffff;
}
